steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Authorization: <TOKEN>" \
  -H "Content-Type: application/json" \
  -d '{
    "query": "
      {
        teams: teams(filter: { name: { eq: \"Web\" } }) {
          nodes {
            id
            name
            states: workflowStates {
              nodes {
                id
                name
                type
              }
            }
          }
        }
        users(filter: { name: { contains: \"Priya Nair\" } }) {
          nodes {
            id
            name
          }
        }
      }
    "
  }'

